import { FunctionsHttpError } from '@supabase/supabase-js';
import { supabase } from './supabase';

export type CommunityPayPageConfig = {
  eyebrow: string;
  headline: string;
  subheadline: string;
  benefitsTitle: string;
  ctaLabel: string;
  footerNote: string;
  accentColor: string;
  coverImageUrl: string;
};

export type CommunitySubscriptionTier = {
  id: string;
  community_id: string;
  name: string;
  description: string | null;
  price: number;
  currency: string;
  interval: 'month' | 'year';
  role_id: string | null;
  slug: string;
  features: string[];
  page_config: CommunityPayPageConfig;
  trial_period_days: number;
  display_order: number;
  is_active: boolean;
  archived_at: string | null;
  created_at: string;
  updated_at: string;
};

export type CommunitySubscriptionPublicPlan = {
  id: string;
  communityId: string;
  name: string;
  description: string;
  slug: string;
  price: number;
  currency: string;
  interval: 'month' | 'year';
  trialPeriodDays: number;
  features: string[];
  pageConfig: CommunityPayPageConfig;
  community: {
    id: string;
    name: string;
    description: string;
    logoUrl: string;
    bannerUrl: string;
  };
};

export type CommunityAnalytics = {
  totalMembers: number;
  newMembers30d: number;
  previousNewMembers30d: number;
  totalMessages: number;
  messages30d: number;
  previousMessages30d: number;
  activeUsers30d: number;
  engagementRate: number;
  activeSubscriptions: number;
  newSubscriptions30d: number;
  canceledSubscriptions30d: number;
  monthlyRunRateByCurrency: Array<{ currency: string; amount: number }>;
  topChannels: Array<{ id: string; name: string; messages30d: number }>;
  trend: Array<{ month: string; members: number; messages: number; subscriptions: number }>;
  generatedAt: string | null;
};

const asRecord = (value: unknown): Record<string, unknown> =>
  value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};

const text = (value: unknown, fallback = '') =>
  typeof value === 'string' && value.trim() ? value.trim() : fallback;

const number = (value: unknown) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

export const communitySubscriptionPath = (communityId: string, slug: string) =>
  `/community/${encodeURIComponent(communityId)}/subscribe/${encodeURIComponent(slug)}`;

export const normalizeCommunityPayPageConfig = (
  value: unknown,
  defaults: { communityName?: string; communityDescription?: string; tierName?: string; accentColor?: string } = {},
): CommunityPayPageConfig => {
  const config = asRecord(value);
  const tierName = defaults.tierName || 'Membership';
  const communityName = defaults.communityName || 'Community';
  const candidateColor = text(config.accentColor, defaults.accentColor || '#7c3aed');
  return {
    eyebrow: text(config.eyebrow, communityName),
    headline: text(config.headline, `Join ${communityName}`),
    subheadline: text(config.subheadline, defaults.communityDescription || `Unlock ${tierName} membership.`),
    benefitsTitle: text(config.benefitsTitle, 'What is included'),
    ctaLabel: text(config.ctaLabel, `Join ${tierName}`),
    footerNote: text(config.footerNote, 'Recurring billing is handled securely by Wersee and Stripe.'),
    accentColor: /^#[0-9a-f]{6}$/i.test(candidateColor) ? candidateColor.toLowerCase() : '#7c3aed',
    coverImageUrl: text(config.coverImageUrl),
  };
};

export const normalizeCommunitySubscriptionTier = (value: unknown): CommunitySubscriptionTier => {
  const tier = asRecord(value);
  const interval = tier.interval === 'year' ? 'year' : 'month';
  return {
    id: text(tier.id),
    community_id: text(tier.community_id),
    name: text(tier.name, 'Membership'),
    description: text(tier.description) || null,
    price: number(tier.price),
    currency: text(tier.currency, 'eur').toLowerCase(),
    interval,
    role_id: text(tier.role_id) || null,
    slug: text(tier.slug, 'membership'),
    features: Array.isArray(tier.features) ? tier.features.map((feature) => text(feature)).filter(Boolean) : [],
    page_config: normalizeCommunityPayPageConfig(tier.page_config, { tierName: text(tier.name, 'Membership') }),
    trial_period_days: Math.max(0, number(tier.trial_period_days)),
    display_order: Math.max(0, number(tier.display_order)),
    is_active: tier.is_active !== false,
    archived_at: text(tier.archived_at) || null,
    created_at: text(tier.created_at),
    updated_at: text(tier.updated_at),
  };
};

export const normalizeCommunityAnalytics = (value: unknown): CommunityAnalytics => {
  const analytics = asRecord(value);
  const topChannels = Array.isArray(analytics.topChannels) ? analytics.topChannels : [];
  const trend = Array.isArray(analytics.trend) ? analytics.trend : [];
  const monthlyRunRateByCurrency = Array.isArray(analytics.monthlyRunRateByCurrency)
    ? analytics.monthlyRunRateByCurrency
    : [];
  return {
    totalMembers: number(analytics.totalMembers),
    newMembers30d: number(analytics.newMembers30d),
    previousNewMembers30d: number(analytics.previousNewMembers30d),
    totalMessages: number(analytics.totalMessages),
    messages30d: number(analytics.messages30d),
    previousMessages30d: number(analytics.previousMessages30d),
    activeUsers30d: number(analytics.activeUsers30d),
    engagementRate: number(analytics.engagementRate),
    activeSubscriptions: number(analytics.activeSubscriptions),
    newSubscriptions30d: number(analytics.newSubscriptions30d),
    canceledSubscriptions30d: number(analytics.canceledSubscriptions30d),
    monthlyRunRateByCurrency: monthlyRunRateByCurrency.map((item) => {
      const rate = asRecord(item);
      return { currency: text(rate.currency, 'eur').toLowerCase(), amount: number(rate.amount) };
    }),
    topChannels: topChannels.map((item) => {
      const channel = asRecord(item);
      return { id: text(channel.id), name: text(channel.name, 'Channel'), messages30d: number(channel.messages30d) };
    }),
    trend: trend.map((item) => {
      const point = asRecord(item);
      return {
        month: text(point.month),
        members: number(point.members),
        messages: number(point.messages),
        subscriptions: number(point.subscriptions),
      };
    }),
    generatedAt: text(analytics.generatedAt) || null,
  };
};

export const metricChange = (current: number, previous: number) => {
  if (previous <= 0) return current > 0 ? 100 : 0;
  return Math.round(((current - previous) / previous) * 100);
};

export const formatCommunitySubscriptionPrice = (
  price: number,
  currency: string,
  locale = 'en-US',
) => new Intl.NumberFormat(locale, {
  style: 'currency',
  currency: currency.toUpperCase(),
  minimumFractionDigits: price % 1 === 0 ? 0 : 2,
  maximumFractionDigits: 2,
}).format(price);

export class CommunitySubscriptionError extends Error {
  code?: string;
  details?: unknown;

  constructor(message: string, code?: string, details?: unknown) {
    super(message);
    this.name = 'CommunitySubscriptionError';
    this.code = code;
    this.details = details;
  }
}

export async function communitySubscriptionAction<T>(action: string, input: Record<string, unknown>): Promise<T> {
  const { data, error } = await supabase.functions.invoke('community-subscriptions', {
    body: { action, input },
  });
  if (error) {
    if (error instanceof FunctionsHttpError) {
      try {
        const payload = await error.context.json();
        throw new CommunitySubscriptionError(payload?.error || error.message, payload?.code, payload?.details);
      } catch (contextError) {
        if (contextError instanceof CommunitySubscriptionError) throw contextError;
      }
    }
    throw new CommunitySubscriptionError(error.message || 'Community subscription request failed.');
  }
  if (!data?.success) throw new CommunitySubscriptionError(data?.error || 'Community subscription request failed.', data?.code, data?.details);
  return data as T;
}
